const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const bellingham = ee.Geometry.Point([-122.482, 48.751]).buffer(5000); // Buffer around Bellingham
  const startDate = '2021-09-01';
  const endDate = '2021-11-30';

  // 2. Data Acquisition - CHIRPS precipitation data
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(bellingham);

  const collectionSize = chirps.size().getInfo();
  console.log(`CHIRPS Images: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Sum precipitation over the period
  const totalPrecip = chirps.sum();

  // 4. Calculate statistics
  const stats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: bellingham,
    scale: 5000,
    maxPixels: 1e9
  });

  const meanPrecip = stats.get('precipitation').getInfo();
  const pixelCount = stats.get('precipitation_count').getInfo();

  console.log(`Mean Precipitation (mm): ${meanPrecip ? meanPrecip.toFixed(1) : 'None'}`);
  console.log(`Valid Pixels: ${pixelCount}`);

  // 5. Validation & Final Answer
  if (pixelCount === 0) {
    console.log("<answer>C2</answer>");
  } else if (meanPrecip === null || meanPrecip === undefined || isNaN(meanPrecip)) {
    console.log("<answer>C3</answer>");
  } else {
    const precipCm = meanPrecip / 10; // Convert mm to cm
    console.log(`Total Precipitation (cm): ${precipCm.toFixed(1)}`);

    if (precipCm >= 30) {
      console.log("<answer>A</answer>");
    } else {
      console.log("<answer>B</answer>");
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
